window.NODE_TYPES=[{"children": [], "code": false, "derives_from": [], "description": "Rules that apply across services.", "documents": [{"derives_from": [], "description": "Every service, what it owns, and who it talks to. Ownership means the\nservice is the only one that writes that data.\n", "document": "context-map", "exposed": true, "extra": false, "required": true, "template": ".uspec/node-types/architecture/context-map.md", "content": "---\ndescription: |\n  Every service, what it owns, and who it talks to. Ownership means the\n  service is the only one that writes that data.\n---\n\n# Context map\n\n## Services\n\n| Service | Owns | Talks to |\n|---|---|---|\n| <service> | <data it is the only writer of> | <services, sync or async> |\n\n## External systems\n\n| System | Purpose | Direction |\n|---|---|---|\n| <provider> | <what for> | <in / out / both> |\n"}, {"derives_from": ["context-map"], "description": "Conventions every service follows. State the rule, then one example.\n", "document": "conventions", "exposed": true, "extra": false, "required": true, "template": ".uspec/node-types/architecture/conventions.md", "content": "---\ndescription: |\n  Conventions every service follows. State the rule, then one example.\nderives_from: [context-map]\n---\n\n# Conventions\n\n## API style\n\n## Errors\n\n## Events\n\n## IDs and time\n"}, {"derives_from": [], "description": "Architecture decisions that still apply. Remove a decision when it no\nlonger applies; history lives in git.\n", "document": "decisions", "exposed": true, "extra": false, "required": false, "template": ".uspec/node-types/architecture/decisions.md", "content": "---\ndescription: |\n  Architecture decisions that still apply. Remove a decision when it no\n  longer applies; history lives in git.\nrequired: false\n---\n\n# Decisions\n\n## <NNNN> <title>\n\n- Context: <why a decision was needed>\n- Decision: <what was decided>\n- Consequences: <what follows from it>\n"}], "instructions": "Architecture holds what every service must follow.\n", "name": "Architecture", "path": ".uspec/node-types/architecture/node-type.yaml", "type": "architecture", "yaml": "name: Architecture\ndescription: Rules that apply across services.\ndocuments:\n  - context-map\n  - conventions\n  - decisions\ninstructions: |\n  Architecture holds what every service must follow.\n"}, {"children": [], "code": true, "derives_from": [], "description": "Shared UI foundations and components.", "documents": [{"derives_from": [], "description": "The tokens every surface uses. Name each token once; components and\nscreens refer to tokens, never to raw values.\n", "document": "foundations", "exposed": true, "extra": false, "required": true, "template": ".uspec/node-types/design-system/foundations.md", "content": "---\ndescription: |\n  The tokens every surface uses. Name each token once; components and\n  screens refer to tokens, never to raw values.\n---\n\n# Foundations\n\n## Colour\n\n## Typography\n\n## Spacing\n\n## Motion\n"}, {"derives_from": [], "description": "Each shared component: what it is for, its variants, and when not to use it.\n", "document": "components", "exposed": true, "extra": false, "required": true, "template": ".uspec/node-types/design-system/components.md", "content": "---\ndescription: |\n  Each shared component: what it is for, its variants, and when not to use it.\n---\n\n# Components\n\n## <Component name>\n\n<What it is for.>\n\n- Variants: <list>\n- Don't use for: <cases>\n"}], "instructions": "The Design system holds UI rules every surface follows. Its code is the\nshared UI package.\n", "name": "Design system", "path": ".uspec/node-types/design-system/node-type.yaml", "type": "design-system", "yaml": "name: Design system\ndescription: Shared UI foundations and components.\ncode: true\ndocuments:\n  - foundations\n  - components\ninstructions: |\n  The Design system holds UI rules every surface follows. Its code is the\n  shared UI package.\n"}, {"children": [], "code": false, "derives_from": ["glossary"], "description": "Core entities and their lifecycles.", "documents": [{"derives_from": [], "description": "Every core entity, its fields and the invariants that always hold.\nUse glossary terms for entity names.\n", "document": "entities", "exposed": true, "extra": false, "required": true, "template": ".uspec/node-types/domain-model/entities.md", "content": "---\ndescription: |\n  Every core entity, its fields and the invariants that always hold.\n  Use glossary terms for entity names.\n---\n\n# Entities\n\n## <Entity>\n\n<What it represents.>\n\n### Fields\n\n| Field | Type | Description |\n|---|---|---|\n| <field> | <type> | <meaning> |\n\n### Invariants\n\n- <Rule that is always true.>\n"}, {"derives_from": ["entities"], "description": "One state machine per aggregate that changes state over time. Every\ntransition names the event that causes it.\n", "document": "lifecycle", "exposed": true, "extra": false, "required": true, "template": ".uspec/node-types/domain-model/lifecycle.md", "content": "---\ndescription: |\n  One state machine per aggregate that changes state over time. Every\n  transition names the event that causes it.\nderives_from: [entities]\n---\n\n# Lifecycles\n\n## <Aggregate>\n\n### States\n\n| State | Meaning |\n|---|---|\n| <STATE> | <what it means> |\n\n### Transitions\n\n| From | Event | To |\n|---|---|---|\n| <STATE> | <event> | <STATE> |\n"}], "instructions": "The Domain model defines entities and state machines shared by all services.\n", "name": "Domain model", "path": ".uspec/node-types/domain-model/node-type.yaml", "type": "domain-model", "yaml": "name: Domain model\ndescription: Core entities and their lifecycles.\nderives_from: [glossary]\ndocuments:\n  - entities\n  - lifecycle\ninstructions: |\n  The Domain model defines entities and state machines shared by all services.\n"}, {"children": ["design-system", "surface", "messaging"], "code": false, "derives_from": [], "description": "What users see, split by surface.", "documents": [{"derives_from": [], "description": "A summary of the surfaces: who uses each one, on which platform.\n", "document": "overview", "exposed": true, "extra": false, "required": true, "template": ".uspec/node-types/experience/overview.md", "content": "---\ndescription: |\n  A summary of the surfaces: who uses each one, on which platform.\n---\n\n# Experience\n\n## Surfaces\n\n<One line per app: audience and platform.>\n\n## Shared\n\n<What all surfaces share: design system, messaging, accessibility level.>\n"}], "instructions": "The experience branch is split by surface (app), then by screen.\n", "name": "Experience", "path": ".uspec/node-types/experience/node-type.yaml", "type": "experience", "yaml": "name: Experience\ndescription: What users see, split by surface.\nchildren: [design-system, surface, messaging]\ndocuments:\n  - overview\ninstructions: |\n  The experience branch is split by surface (app), then by screen.\n"}, {"children": [], "code": false, "derives_from": ["glossary"], "description": "One user problem and the behaviour that solves it.", "documents": [{"derives_from": [], "description": "One user problem in product terms. Name no services, apps or screens.\nEvery acceptance criterion must be testable and written as\nGiven / When / Then.\n", "document": "user-story", "exposed": true, "extra": false, "required": true, "template": ".uspec/node-types/feature/user-story.md", "content": "---\ndescription: |\n  One user problem in product terms. Name no services, apps or screens.\n  Every acceptance criterion must be testable and written as\n  Given / When / Then.\n---\n\n# <Feature name>\n\n## Story\n\nAs a <user>, I want <goal>, so that <reason>.\n\n## Acceptance criteria\n\n- Given <context>, when <action>, then <outcome>.\n\n## Out of scope\n\n- <Related behaviour this feature does not cover.>\n"}, {"derives_from": ["user-story"], "description": "Business rules in product terms: limits, eligibility, calculations.\nAdd it only when the user story can't hold the rules. One rule per\nbullet, each with an example.\n", "document": "rules", "exposed": true, "extra": false, "required": false, "template": ".uspec/node-types/feature/rules.md", "content": "---\ndescription: |\n  Business rules in product terms: limits, eligibility, calculations.\n  Add it only when the user story can't hold the rules. One rule per\n  bullet, each with an example.\nrequired: false\nderives_from: [user-story]\n---\n\n# Rules\n\n- <Rule.> Example: <concrete case.>\n"}], "instructions": "A Feature describes one user problem in product terms. It lists no code\npaths and names no services or apps; those link to it, not the other way round.\n", "name": "Feature", "path": ".uspec/node-types/feature/node-type.yaml", "type": "feature", "yaml": "name: Feature\ndescription: One user problem and the behaviour that solves it.\nderives_from: [glossary]\ndocuments:\n  - user-story\n  - rules\ninstructions: |\n  A Feature describes one user problem in product terms. It lists no code\n  paths and names no services or apps; those link to it, not the other way round.\n"}, {"children": [], "code": false, "derives_from": [], "description": "Shared product vocabulary.", "documents": [{"derives_from": [], "description": "Every word with a specific meaning in this product. Use these terms,\nand only these, everywhere else in the spec.\n", "document": "terms", "exposed": true, "extra": false, "required": true, "template": ".uspec/node-types/glossary/terms.md", "content": "---\ndescription: |\n  Every word with a specific meaning in this product. Use these terms,\n  and only these, everywhere else in the spec.\n---\n\n# Glossary\n\n## Terms\n\n| Term | Meaning | Not to confuse with |\n|---|---|---|\n| <term> | <one-sentence meaning> | <similar term, or \u2014> |\n"}], "instructions": "The Glossary defines words the whole spec uses: order, basket, payout, courier shift.\n", "name": "Glossary", "path": ".uspec/node-types/glossary/node-type.yaml", "type": "glossary", "yaml": "name: Glossary\ndescription: Shared product vocabulary.\ndocuments:\n  - terms\ninstructions: |\n  The Glossary defines words the whole spec uses: order, basket, payout, courier shift.\n"}, {"children": [], "code": true, "derives_from": ["feature"], "description": "Email, SMS and push templates.", "documents": [{"derives_from": [], "description": "Every message the product sends outside the apps. One section per\nmessage, named by its id.\n", "document": "templates", "exposed": true, "extra": false, "required": true, "template": ".uspec/node-types/messaging/templates.md", "content": "---\ndescription: |\n  Every message the product sends outside the apps. One section per\n  message, named by its id.\n---\n\n# Messages\n\n## <message-id>\n\n- Channel: <email | sms | push>\n- Trigger: <what sends it>\n- Audience: <who receives it>\n- Copy: <text, with {placeholders}>\n"}], "instructions": "Messaging holds every message the product sends outside the apps.\n", "name": "Messaging", "path": ".uspec/node-types/messaging/node-type.yaml", "type": "messaging", "yaml": "name: Messaging\ndescription: Email, SMS and push templates.\ncode: true\nderives_from: [feature]\ndocuments:\n  - templates\ninstructions: |\n  Messaging holds every message the product sends outside the apps.\n"}, {"children": [], "code": true, "derives_from": ["architecture"], "description": "Infrastructure, deploys, observability.", "documents": [{"derives_from": [], "description": "Where and how services run. Describe the target state, not the migration to it.\n", "document": "infra", "exposed": true, "extra": false, "required": true, "template": ".uspec/node-types/platform/infra.md", "content": "---\ndescription: |\n  Where and how services run. Describe the target state, not the migration to it.\n---\n\n# Platform\n\n## Environments\n\n## Deploy\n\n## Observability\n\n## Secrets\n"}], "instructions": "Platform describes where and how services run.\n", "name": "Platform", "path": ".uspec/node-types/platform/node-type.yaml", "type": "platform", "yaml": "name: Platform\ndescription: Infrastructure, deploys, observability.\ncode: true\nderives_from: [architecture]\ndocuments:\n  - infra\ninstructions: |\n  Platform describes where and how services run.\n"}, {"children": ["product-area", "glossary"], "code": false, "derives_from": [], "description": "What and why, split by user problem.", "documents": [{"derives_from": [], "description": "A summary of the product areas and how users move between them.\nWritten from the areas below; update it when an area is added or changes.\n", "document": "overview", "exposed": true, "extra": false, "required": true, "template": ".uspec/node-types/product/overview.md", "content": "---\ndescription: |\n  A summary of the product areas and how users move between them.\n  Written from the areas below; update it when an area is added or changes.\n---\n\n# Product\n\n## Areas\n\n<One line per product area: name, and the user problem it covers.>\n\n## How the areas connect\n\n<The main journeys that cross areas, e.g. discovery \u2192 ordering \u2192 delivery.>\n"}], "instructions": "The product branch describes user problems. It never names services,\napps, screens or code.\n", "name": "Product", "path": ".uspec/node-types/product/node-type.yaml", "type": "product", "yaml": "name: Product\ndescription: What and why, split by user problem.\nchildren: [product-area, glossary]\ndocuments:\n  - overview\ninstructions: |\n  The product branch describes user problems. It never names services,\n  apps, screens or code.\n"}, {"children": ["product-area", "feature"], "code": false, "derives_from": [], "description": "A group of related user problems.", "documents": [{"derives_from": [], "description": "What this area covers and where it stops. Summarise the features\nbelow; don't repeat their user stories.\n", "document": "overview", "exposed": true, "extra": false, "required": true, "template": ".uspec/node-types/product-area/overview.md", "content": "---\ndescription: |\n  What this area covers and where it stops. Summarise the features\n  below; don't repeat their user stories.\n---\n\n# <Area name>\n\n<Which user problem this area covers, and for whom.>\n\n## Features\n\n<One line per feature.>\n\n## Boundaries\n\n<What belongs to a neighbouring area instead.>\n"}], "instructions": "A Product area groups features by the user problem they solve. Areas may nest.\n", "name": "Product area", "path": ".uspec/node-types/product-area/node-type.yaml", "type": "product-area", "yaml": "name: Product area\ndescription: A group of related user problems.\nchildren: [product-area, feature]\ndocuments:\n  - overview\ninstructions: |\n  A Product area groups features by the user problem they solve. Areas may nest.\n"}, {"children": ["product", "experience", "system"], "code": false, "derives_from": [], "description": "Top of the spec tree.", "documents": [{"derives_from": [], "description": "The product on one page: what it is, who it is for, what it is not.\nWrite for someone who has never heard of the product. Keep it stable:\nit changes only when the product's direction changes.\n", "document": "overview", "exposed": true, "extra": false, "required": true, "template": ".uspec/node-types/root/overview.md", "content": "---\ndescription: |\n  The product on one page: what it is, who it is for, what it is not.\n  Write for someone who has never heard of the product. Keep it stable:\n  it changes only when the product's direction changes.\n---\n\n# <Product name>\n\n<One paragraph: what the product does and for whom.>\n\n## Users\n\n<Each kind of user and what they come for.>\n\n## Scope\n\n<What the product does, in a few bullets.>\n\n## Out of scope\n\n<What it deliberately does not do.>\n\n## Constraints\n\n<Hard constraints every part of the spec must respect: platforms, regions, regulation.>\n"}], "instructions": "The root splits the spec into three branches, each cut along its own\nboundaries: product by user problem, experience by surface, system by service.\n", "name": "Product spec", "path": ".uspec/node-types/root/node-type.yaml", "type": "root", "yaml": "name: Product spec\ndescription: Top of the spec tree.\nchildren: [product, experience, system]\ndocuments:\n  - overview\ninstructions: |\n  The root splits the spec into three branches, each cut along its own\n  boundaries: product by user problem, experience by surface, system by service.\n"}, {"children": [], "code": true, "derives_from": ["feature", "design-system", "service"], "description": "One user-facing flow inside a surface.", "documents": [{"derives_from": [], "description": "How the screen looks and behaves. Link design frames; describe what\nthe frames can't show (interactions, edge cases, copy rules).\n", "document": "design", "exposed": true, "extra": false, "required": true, "template": ".uspec/node-types/screen/design.md", "content": "---\ndescription: |\n  How the screen looks and behaves. Link design frames; describe what\n  the frames can't show (interactions, edge cases, copy rules).\n---\n\n# <Screen name>\n\n## Purpose\n\n<Which features this screen serves and what the user gets done here.>\n\n## Layout\n\n## Interactions\n\n## Copy\n\n## Design frames\n\n<Links to the frames.>\n"}, {"derives_from": ["design"], "description": "Every state the screen can be in and what moves it between them.\nInclude loading, empty and error states. Events are user actions or\nAPI results from the services this screen calls.\n", "document": "states", "exposed": true, "extra": false, "required": true, "template": ".uspec/node-types/screen/states.md", "content": "---\ndescription: |\n  Every state the screen can be in and what moves it between them.\n  Include loading, empty and error states. Events are user actions or\n  API results from the services this screen calls.\nderives_from: [design]\n---\n\n# States\n\n## States\n\n| State | When | What the user sees |\n|---|---|---|\n| <state> | <condition> | <description> |\n\n## Transitions\n\n| From | Event | To |\n|---|---|---|\n| <state> | <user action or API result> | <state> |\n"}], "instructions": "A Screen is one user-facing flow in one app. It may serve several features,\nand one feature may appear on several screens; links show that. It is\nbuilt against the API of the service it calls.\n", "name": "Screen", "path": ".uspec/node-types/screen/node-type.yaml", "type": "screen", "yaml": "name: Screen\ndescription: One user-facing flow inside a surface.\ncode: true\nderives_from: [feature, design-system, service]\ndocuments:\n  - design\n  - states\ninstructions: |\n  A Screen is one user-facing flow in one app. It may serve several features,\n  and one feature may appear on several screens; links show that. It is\n  built against the API of the service it calls.\n"}, {"children": [], "code": true, "derives_from": ["feature", "domain-model", "architecture"], "description": "One deployable backend service.", "documents": [{"derives_from": [], "description": "The service's contract: every endpoint (REST) or operation (GraphQL)\nother services and apps call. This is the document screens are built\nagainst; changing it affects every node that derives from this service.\nPut machine-readable schemas (OpenAPI, GraphQL SDL) in api-extra/.\n", "document": "api", "exposed": true, "extra": true, "required": true, "template": ".uspec/node-types/service/api.md", "content": "---\ndescription: |\n  The service's contract: every endpoint (REST) or operation (GraphQL)\n  other services and apps call. This is the document screens are built\n  against; changing it affects every node that derives from this service.\n  Put machine-readable schemas (OpenAPI, GraphQL SDL) in api-extra/.\nextra: true\n---\n\n# <Service> API\n\n<Style (REST or GraphQL), base path, authentication.>\n\n## <operation>\n\n<What it does and who calls it.>\n\n### Request\n\n| Field | Type | Required | Description |\n|---|---|---|---|\n| <field> | <type> | <yes/no> | <meaning> |\n\n### Response\n\n| Field | Type | Description |\n|---|---|---|\n| <field> | <type> | <meaning> |\n\n### Errors\n\n| Status | Code | When |\n|---|---|---|\n| <HTTP status> | <error code> | <condition> |\n"}, {"derives_from": ["api"], "description": "Business rules and invariants inside the service. Service-wide rules\n(idempotency, ledgers) live here once, not in every feature.\n", "document": "logic", "exposed": false, "extra": false, "required": true, "template": ".uspec/node-types/service/logic.md", "content": "---\ndescription: |\n  Business rules and invariants inside the service. Service-wide rules\n  (idempotency, ledgers) live here once, not in every feature.\nderives_from: [api]\nexposed: false\n---\n\n# <Service> logic\n\n## Responsibilities\n\n## Rules\n\n## Idempotency and retries\n"}, {"derives_from": ["logic"], "description": "Every table the service owns. No other service reads or writes them.\n", "document": "storage", "exposed": false, "extra": false, "required": false, "template": ".uspec/node-types/service/storage.md", "content": "---\ndescription: |\n  Every table the service owns. No other service reads or writes them.\nrequired: false\nderives_from: [logic]\nexposed: false\n---\n\n# Storage\n\n## <table>\n\n### Columns\n\n| Column | Type | Null | Description |\n|---|---|---|---|\n| <column> | <type> | <yes/no> | <meaning> |\n\n### Indexes\n\n- <columns> \u2014 <why>\n"}, {"derives_from": ["logic"], "description": "Events the service emits and consumes. Emitted events are part of its\ncontract, like the API.\n", "document": "events", "exposed": true, "extra": false, "required": false, "template": ".uspec/node-types/service/events.md", "content": "---\ndescription: |\n  Events the service emits and consumes. Emitted events are part of its\n  contract, like the API.\nrequired: false\nderives_from: [logic]\n---\n\n# Events\n\n## Emits\n\n| Event | When | Payload |\n|---|---|---|\n| <EventName> | <condition> | <fields> |\n\n## Consumes\n\n| Event | From | Reaction |\n|---|---|---|\n| <EventName> | <service> | <what this service does> |\n"}, {"derives_from": [], "description": "Regulatory scope (PCI, GDPR, ...) and the controls that keep the service in it.\n", "document": "compliance", "exposed": false, "extra": false, "required": false, "template": ".uspec/node-types/service/compliance.md", "content": "---\ndescription: |\n  Regulatory scope (PCI, GDPR, ...) and the controls that keep the service in it.\nrequired: false\nexposed: false\n---\n\n# Compliance\n\n## Scope\n\n## Controls\n\n## Data retention\n"}], "instructions": "A Service is one deployable backend service, and the only owner of its\ncode. Service-wide rules (idempotency, ledgers, compliance scope) live here\nonce. A Service derives from the features it serves. It never derives from\nthe experience branch: screens are built against its API, not the other\nway round.\n", "name": "Service", "path": ".uspec/node-types/service/node-type.yaml", "type": "service", "yaml": "name: Service\ndescription: One deployable backend service.\ncode: true\nderives_from: [feature, domain-model, architecture]\ndocuments:\n  - api\n  - logic\n  - storage\n  - events\n  - compliance\ninstructions: |\n  A Service is one deployable backend service, and the only owner of its\n  code. Service-wide rules (idempotency, ledgers, compliance scope) live here\n  once. A Service derives from the features it serves. It never derives from\n  the experience branch: screens are built against its API, not the other\n  way round.\n"}, {"children": ["service"], "code": false, "derives_from": [], "description": "All backend services.", "documents": [{"derives_from": [], "description": "Every service with one line of responsibility. Written from the service nodes below.\n", "document": "overview", "exposed": true, "extra": false, "required": true, "template": ".uspec/node-types/services/overview.md", "content": "---\ndescription: |\n  Every service with one line of responsibility. Written from the service nodes below.\n---\n\n# Services\n\n## Services\n\n| Service | Responsibility |\n|---|---|\n| <service> | <one line> |\n"}], "instructions": "Groups the service nodes.\n", "name": "Services", "path": ".uspec/node-types/services/node-type.yaml", "type": "services", "yaml": "name: Services\ndescription: All backend services.\nchildren: [service]\ndocuments:\n  - overview\ninstructions: |\n  Groups the service nodes.\n"}, {"children": ["screen"], "code": true, "derives_from": ["design-system", "architecture"], "description": "One client app.", "documents": [{"derives_from": [], "description": "What belongs to the app as a whole and to no single screen. Its code\npaths cover the shell only; screens own their own folders.\n", "document": "shell", "exposed": true, "extra": false, "required": true, "template": ".uspec/node-types/surface/shell.md", "content": "---\ndescription: |\n  What belongs to the app as a whole and to no single screen. Its code\n  paths cover the shell only; screens own their own folders.\n---\n\n# <App name> shell\n\n## Navigation\n\n## Session\n\n## Offline\n\n## Deep links\n"}], "instructions": "A Surface is one client app. It owns navigation, session and offline\nbehaviour. Its code paths cover the shell only.\n", "name": "Surface", "path": ".uspec/node-types/surface/node-type.yaml", "type": "surface", "yaml": "name: Surface\ndescription: One client app.\ncode: true\nchildren: [screen]\nderives_from: [design-system, architecture]\ndocuments:\n  - shell\ninstructions: |\n  A Surface is one client app. It owns navigation, session and offline\n  behaviour. Its code paths cover the shell only.\n"}, {"children": ["architecture", "domain-model", "services", "platform"], "code": false, "derives_from": [], "description": "How it works, split by service.", "documents": [{"derives_from": [], "description": "A summary of the system: its services and how they talk.\n", "document": "overview", "exposed": true, "extra": false, "required": true, "template": ".uspec/node-types/system/overview.md", "content": "---\ndescription: |\n  A summary of the system: its services and how they talk.\n---\n\n# System\n\n## Shape\n\n<Services, how they communicate, where data lives.>\n"}], "instructions": "The system branch follows the real architecture: services, shared model, platform.\n", "name": "System", "path": ".uspec/node-types/system/node-type.yaml", "type": "system", "yaml": "name: System\ndescription: How it works, split by service.\nchildren: [architecture, domain-model, services, platform]\ndocuments:\n  - overview\ninstructions: |\n  The system branch follows the real architecture: services, shared model, platform.\n"}];